/// <summary>
/// CustTable associated with CustomerAccount field
/// </summary>
/// <returns>CustTable record if found, null otherwise</returns>
public CustTable custTable()
{
    return CustTable::find(this.CustomerAccount);
}

/// <summary>
/// VenTable record associated with VendorAccount field
/// </summary>
/// <returns>VendTable record if found, null otherwise</returns>
public VendTable vendTable()
{
    return VendTable::find(this.VendorAccount);
}

    /// <summary>
    /// Set default value on the table fields
    /// </summary>
    public void initValue()
    {
        // CB411_412_ChargeThrough currency set from vendor, moved to initFromVendTable
        //this.CurrencyCode = Ledger::accountingCurrency(CompanyInfo::current());
        this.TransactionDate =  DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        // CB194_ChargeThroughClaims
        this.ClaimStatus = METReturnStatus::NotRequired;

        super();
    }

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METCBCTInvoiceHeaderTable, CustomerAccount):
                this.initFromCustTable(this.custTable());
                this.assignFinancialDimension();
                this.setDueDates();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable, VendorAccount):
                this.initFromVendTable(this.vendTable());
                this.assignFinancialDimension();
                this.setDueDates();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable,CustPaymTermId):
            case fieldNum(METCBCTInvoiceHeaderTable,VendPaymTermId):
                this.setDueDates();
                break;

        }
    }

/// <summary>
/// Set financial dimension on the line.
/// </summary>
private void assignFinancialDimension()
{
    CustTable       custTable = CustTable::find(this.CustomerAccount);
    VendTable       vendTable = VendTable::find(this.VendorAccount);
    if (custTable.RecId && vendTable.RecId)
    {
        this.FinancialDimension = DimensionDefaultFacade::serviceMergeDefaultDimensions(vendTable.DefaultDimension,custTable.DefaultDimension);
    }
    else if (custTable.RecId)
    {
        this.FinancialDimension = custTable.DefaultDimension;
    }
   
}

/// <summary>
/// MPJ_37288_ChargebackChargethrough_extension functionalities(MPJ_3587)
/// Set due dates
/// </summary>
public void setDueDates()
{
    // CB411_412_ChargeThrough
    METVendParameters metVendParameters = METVendParameters::find();
    if(metVendParameters)
    {            
        if (this.CustPaymTermId)
        {
            switch(metVendParameters.CustDueDateBasis)
            {
                case METCBCTCustDueDateBasis::TransactionDate :                      
                    this.CustDueDate = PaymTerm::find(this.CustPaymTermId).due(this.TransactionDate);
                    break;
                case METCBCTCustDueDateBasis::VendorInvoiceDate :
                    this.CustDueDate = PaymTerm::find(this.CustPaymTermId).due(this.DocumentDate);
                    break;
            }
        
        }
        if (this.VendPaymTermId)
        {
            // Always using the TransactionDate
            this.VendDueDate = PaymTerm::find(this.VendPaymTermId).due(this.TransactionDate);                
        }
    }
}

    /// <summary>
    /// Set profit centre
    /// </summary>
    /// <param name = "_defaultDimension">
    /// Dimension default value
    /// </param>
    ///  <param name = "_dimensionName">
    /// Dimension name
    /// </param>
    ///  <param name = "_dimensionValue">
    /// Dimension value
    /// </param>
    public void setCostCentre(DimensionDefault _defaultDimension,
                                Name             _dimensionName,
                                DimensionValue   _dimensionValue)
    {
        //'ProfitCentre'
        DimensionAttribute                  dimAttribute;
        DimensionAttributeValue             dimAttributeValue;
        DimensionAttributeValueSetStorage   dimStorage;

        dimStorage      = DimensionAttributeValueSetStorage::find(_defaultDimension);
        dimAttribute    = DimensionAttribute::findByName(_dimensionName);

        if (_dimensionValue)
        {
            dimAttributeValue = DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttribute, _dimensionValue, true, true);
            dimStorage.addItem(dimAttributeValue);
        }
        else
        {
            dimStorage.removeDimensionAttribute(dimAttribute.RecId);
        }

        this.FinancialDimension = dimStorage.save();
    }

    /// <summary>
    /// Defaults cost centre
    /// </summary>
    /// <returns>
    /// Cost centre dimension value
    /// </returns>
    public DimensionValue defaultCostCentre()
    {
        DimensionValue                              costCentreValue;

        METCBCTCustomerSiteOffRemitCostCentreLink   customerSiteOffRemitCostCentreLink;
        InventSiteId                                inventSiteId = CustTable::find(this.CustomerAccount).InventSiteId;

        select firstonly customerSiteOffRemitCostCentreLink 
                   where customerSiteOffRemitCostCentreLink.InventSiteId == inventSiteId;

        if (customerSiteOffRemitCostCentreLink.RecId)
        {
            costCentreValue = customerSiteOffRemitCostCentreLink.CostCentre;
        }
        
        return costCentreValue;
    }

    /// <summary>
    /// Performs validation on fields
    /// </summary>
    /// <param name = "_fieldIdToCheck">
    /// Field ID for which the value need to be validated
    /// </param>
    /// <returns>
    /// Boolean value
    /// </returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        switch (_fieldIdToCheck)
        {
            case fieldNum(METCBCTInvoiceHeaderTable, VendorAccount):
                ret = ret && this.validateVendorAccount();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable, CustomerAccount):
                ret = ret && this.validateCustomerAccount();
                break;
        }
        return ret;
    }

/// <summary>
/// Validates value of selected vendor account
/// </summary>
/// <returns>
/// True if the vendor is Charge through vendor
/// </returns>
public boolean validateVendorAccount()
{
    METVendTable metVendTable = METVendTable::find(this.VendorAccount);
    return metVendTable.AllowChargeThrough || metVendTable.AllowCrossDock ? true : checkFailed("@MET:VendorNotPermittedForChargethrough");
}

/// <summary>
/// Validates value of selected customer account
/// </summary>
/// <returns>
/// True if the customer has signed up for the Charge through process
/// </returns>
public boolean validateCustomerAccount()
{
    METCustTable metCustTable = METCustTable::find(this.CustomerAccount);
    return metCustTable.AllowChargeThrough || metCustTable.AllowCrossDock ? true : checkFailed("@MET:CustomerNotValidForChargethrough");
}

    /// <summary>
    /// MPJ-31514
    /// </summary>
    public void insert()
    {
        this.assignFinancialDimension();
        this.setDueDates();

        super();

        this.autoCreateLines();
    }

